def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 < 50000:
        result = 2019
    elif v2 < 50000:
        result = 2018
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "2019_expenses": v1,
            "2018_expenses": v2,
            "threshold": 50000,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
